#include "ark/agent.hpp"
#include "ark/plane_sections_024b.hpp"
#include "ark/serialize.hpp"
#include "ark/sketch.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
using V=arkjson::Value;
namespace {
int checks=0;
void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);++checks;}
V json(const char* text){V value;check(arkjson::parse(text,value),"test JSON");return value;}
V accepted(const V& response){if(response.find("isError")->b)throw std::runtime_error(response.find("structuredContent")->dump());return *response.find("structuredContent");}
void apply(ark::AgentSession& session,const V& commands){V args=V::makeObj();args.set("expected_revision",V::makeNum(session.revision));args.set("commands",commands);accepted(session.call("doc_apply",args));}
V action(ark::AgentSession& session,const char* request){const auto recipe=ark::planeSectionRecipe(session.document,json(request));apply(session,*recipe.find("commands"));return recipe;}
void initial(ark::AgentSession& session){apply(session,json(R"([{"op":"param.set","name":"CutY","expr":10},{"op":"param.set","name":"PlaneHeight","expr":15},{"op":"sketch.set","name":"Guide","sketch":{"plane":"XY","entities":[{"kind":"line","name":"cut","dof":[-5,"CutY",15,"CutY"]}]}},{"op":"feature.add","type":"native_solid","name":"Block","native":{"op":"box"},"p":{"width":10,"depth":20,"height":30}}])"));}
bool rejects(const ark::Document& document,const char* arguments){try{ark::planeSectionRecipe(document,json(arguments));return false;}catch(const std::exception&){return true;}}
void planes(){
    ark::AgentSession session;initial(session);const auto before=ark::documentToJson(session.document);const auto prepared=ark::planeSectionRecipe(session.document,json(R"({"action":"create_plane","name":"Raised","parent":"XY","p":{"oz":"PlaneHeight","rz":30}})"));check(ark::documentToJson(session.document)==before,"recipe preparation does not mutate document");apply(session,*prepared.find("commands"));check(std::abs(ark::resolvePlane(session.document,"Raised").m[14]-15)<1e-8,"created plane resolves authored offset");
    action(session,R"({"action":"offset_plane","name":"Offset","plane":"Raised","offset":"PlaneHeight/3"})");check(std::abs(ark::resolvePlane(session.document,"Offset").m[14]-20)<1e-8,"offset plane follows saved parent normal");const auto original=ark::sketchToJson(session.document.findSketch("Guide")->sk);auto replane=ark::planeSectionRecipe(session.document,json(R"({"action":"sketch_to_plane","sketch":"Guide","plane":"Offset"})"));V expected;check(arkjson::parse(original,expected),"saved sketch source parses");expected.set("plane",V::makeStr("Offset"));check(replane.find("commands")->arr[0].find("sketch")->dump()==expected.dump(),"sketch reassignment preserves complete entity and expression recipe");apply(session,*replane.find("commands"));check(session.document.findSketch("Guide")->sk.plane=="Offset","sketch now owns requested saved plane");
    apply(session,json(R"([{"op":"param.set","name":"PlaneHeight","expr":18}])"));check(std::abs(ark::resolvePlane(session.document,"Offset").m[14]-24)<1e-8,"parent and offset expressions recompute associatively");check(rejects(session.document,R"({"action":"create_plane","name":"Raised"})"),"duplicate plane never silently overwrites saved datum");check(rejects(session.document,R"({"action":"sketch_to_plane","sketch":"Guide","plane":"Missing"})"),"missing target plane rejects");check(rejects(session.document,R"({"action":"offset_plane","name":"Bad","plane":"XY","offset":"Missing+1"})"),"invalid offset expression rejects");
}
void sections(){
    ark::AgentSession session;initial(session);action(session,R"({"action":"create_plane","name":"Cross","p":{"oz":"PlaneHeight"}})");action(session,R"({"action":"section","id":"Block","name":"Cross contour","plane":"Cross","mode":"contour"})");const auto& contour=session.document.evalBodies.back().nativeData;check(std::abs(contour.find("report")->find("length_mm")->num-60)<1e-7,"saved plane creates exact rectangular section perimeter");check(session.document.features.front().nativeSpec.find("op")->str=="box","section preserves original body recipe");
    action(session,R"({"action":"section_from_line","id":"Block","name":"Line contour","sketch":"Guide","entity":"cut","mode":"contour"})");check(session.document.planes.size()==3,"line section retains axis and perpendicular plane datums");auto frame=ark::resolvePlane(session.document,"Line contour.plane");check(std::abs(frame.m[9]+1)<1e-8,"line section plane normal follows directed line and source plane");check(std::abs(session.document.evalBodies.back().nativeData.find("report")->find("length_mm")->num-80)<1e-7,"line section yields exact 10 by30 contour");
    action(session,R"({"action":"section_from_line","id":"Block","name":"Kept side","sketch":"Guide","entity":"cut","mode":"positive"})");check(std::abs(session.document.evalBodies.back().nativeData.find("report")->find("volume_mm3")->num-3000)<1e-5,"positive line-defined plane retains correct exact half-space");apply(session,json(R"([{"op":"param.set","name":"CutY","expr":12}])"));check(std::abs(session.document.evalBodies.back().nativeData.find("report")->find("volume_mm3")->num-3600)<1e-5,"sketch endpoint expression updates associated cut plane and solid");
    const auto saved=ark::documentToJson(session.document);ark::Document loaded;std::string error;check(ark::documentFromJson(saved,loaded,&error),"plane and line section source loads");loaded.recompute();check(loaded.lastResults.back().ok&&std::abs(loaded.evalBodies.back().nativeData.find("report")->find("volume_mm3")->num-3600)<1e-5,"saved line endpoints remain geometric authority after reload");check(rejects(session.document,R"({"action":"section_from_line","id":"Block","name":"Bad","sketch":"Guide","entity":"missing"})"),"missing line identity rejects");check(rejects(session.document,R"({"action":"section","id":"Line contour","name":"Bad","plane":"Cross"})"),"curve cannot impersonate source solid");check(rejects(session.document,R"({"action":"section","id":"Block","name":"Bad","plane":"Cross","mode":"discard"})"),"unsupported keep mode rejects");
    ark::AgentSession both;initial(both);action(both,R"({"action":"create_plane","name":"Mid","p":{"oz":15}})");action(both,R"({"action":"section","id":1,"name":"Two halves","plane":"Mid","mode":"both"})");check(both.document.evalBodies.back().nativeData.find("report")->find("solids")->num==2&&std::abs(both.document.evalBodies.back().nativeData.find("report")->find("volume_mm3")->num-6000)<1e-5,"both mode keeps two exact parts and total material");
}
}
int main(){try{planes();sections();std::cout<<"plane section authoring tests passed: "<<checks<<" checks\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
